import{_ as o,o as t,c as e,a2 as i}from"./chunks/framework.CBxkvBm_.js";const u=JSON.parse('{"title":"Nelson-Oppen Theory Combination & SMT Solvers","description":"","frontmatter":{},"headers":[],"relativePath":"algorithms/theory-coordinator.md","filePath":"algorithms/theory-coordinator.md"}'),r={name:"algorithms/theory-coordinator.md"};function n(s,a,l,c,d,m){return t(),e("div",null,[...a[0]||(a[0]=[i('<h1 id="nelson-oppen-theory-combination-smt-solvers" tabindex="-1">Nelson-Oppen Theory Combination &amp; SMT Solvers <a class="header-anchor" href="#nelson-oppen-theory-combination-smt-solvers" aria-label="Permalink to &quot;Nelson-Oppen Theory Combination &amp; SMT Solvers&quot;">​</a></h1><p><strong>Implementation</strong>: <a href="https://github.com/modelscript/modelscript/tree/main/packages/runtime/src/formal/" target="_blank" rel="noreferrer"><code>packages/runtime/src/formal/</code></a></p><hr><h2 id="_1-nelson-oppen-cooperation-dpll-t" tabindex="-1">1. Nelson-Oppen Cooperation &amp; DPLL(T) <a class="header-anchor" href="#_1-nelson-oppen-cooperation-dpll-t" aria-label="Permalink to &quot;1. Nelson-Oppen Cooperation &amp; DPLL(T)&quot;">​</a></h2><h3 id="academic-citations" tabindex="-1">Academic Citations <a class="header-anchor" href="#academic-citations" aria-label="Permalink to &quot;Academic Citations&quot;">​</a></h3><ul><li><strong>Nelson, G., &amp; Oppen, D. C. (1979)</strong>. <em>&quot;Simplification by cooperating decision procedures.&quot;</em><br><strong>ACM Transactions on Programming Languages and Systems (TOPLAS)</strong>, 1(2), pp. 245–257.<br> DOI: <a href="https://doi.org/10.1145/357073.357079" target="_blank" rel="noreferrer">10.1145/357073.357079</a></li><li><strong>Nieuwenhuis, R., Oliveras, A., &amp; Tinelli, C. (2006)</strong>. <em>&quot;Solving SAT and SAT Modulo Theories: From an abstract Davis--Putnam--Logemann--Loveland procedure to DPLL(T).&quot;</em><br><strong>Journal of the ACM</strong>, 53(6), pp. 937–977.<br> DOI: <a href="https://doi.org/10.1145/1217856.1217859" target="_blank" rel="noreferrer">10.1145/1217856.1217859</a></li></ul><h3 id="modelscript-rationale-modifications" tabindex="-1">ModelScript Rationale &amp; Modifications <a class="header-anchor" href="#modelscript-rationale-modifications" aria-label="Permalink to &quot;ModelScript Rationale &amp; Modifications&quot;">​</a></h3><p>Proves cross-domain assertions spanning discrete architectural modes, differential equations, interval constraints, and 3D CAD collisions.</p><ul><li><strong>Modifications</strong>: Extended beyond traditional software theories (uninterpreted functions, bit-vectors) to <strong>12 engineering domains</strong> including OWL2 Description Logic, CAD B-Rep spatial physics, and DAE continuous trajectories; combines learned conflict clause propagation with Salsa query invalidation.</li></ul><hr><h2 id="_2-cdcl-sat-solver-with-vsids" tabindex="-1">2. CDCL SAT Solver with VSIDS <a class="header-anchor" href="#_2-cdcl-sat-solver-with-vsids" aria-label="Permalink to &quot;2. CDCL SAT Solver with VSIDS&quot;">​</a></h2><h3 id="academic-citations-1" tabindex="-1">Academic Citations <a class="header-anchor" href="#academic-citations-1" aria-label="Permalink to &quot;Academic Citations&quot;">​</a></h3><ul><li><strong>Silva, J. P. M., &amp; Sakallah, K. A. (1999)</strong>. <em>&quot;GRASP: A search algorithm for propositional satisfiability.&quot;</em><br><strong>IEEE Transactions on Computers</strong>, 48(5), pp. 506–521. DOI: <a href="https://doi.org/10.1109/12.769433" target="_blank" rel="noreferrer">10.1109/12.769433</a></li><li><strong>Moskewicz, M. W., et al. (2001)</strong>. <em>&quot;Chaff: Accelerating SAT design verification.&quot;</em><br><strong>ACM/IEEE Design Automation Conference (DAC)</strong>, pp. 530–535. DOI: <a href="https://doi.org/10.1145/378239.379017" target="_blank" rel="noreferrer">10.1145/378239.379017</a></li></ul><h3 id="modelscript-rationale-modifications-1" tabindex="-1">ModelScript Rationale &amp; Modifications <a class="header-anchor" href="#modelscript-rationale-modifications-1" aria-label="Permalink to &quot;ModelScript Rationale &amp; Modifications&quot;">​</a></h3><p>Solves propositional satisfiability for discrete mode selection, architectural state machines, and CDCL(T) theory case splitting.</p><ul><li><strong>Modifications</strong>: Two-watched-literals data structure with contiguous integer arrays; Variable State Independent Decaying Sum (VSIDS) decision heuristic; 1-UIP (First Unique Implication Point) conflict analysis; Luby-sequence restart schedule.</li></ul><hr><h2 id="_3-craig-interpolation" tabindex="-1">3. Craig Interpolation <a class="header-anchor" href="#_3-craig-interpolation" aria-label="Permalink to &quot;3. Craig Interpolation&quot;">​</a></h2><h3 id="academic-citations-2" tabindex="-1">Academic Citations <a class="header-anchor" href="#academic-citations-2" aria-label="Permalink to &quot;Academic Citations&quot;">​</a></h3><ul><li><strong>Craig, W. (1957)</strong>. <em>&quot;Linear reasoning. A new form of the Herbrand-Gentzen theorem.&quot;</em><br><strong>Journal of Symbolic Logic</strong>, 22(3), pp. 250–268. DOI: <a href="https://doi.org/10.2307/2963593" target="_blank" rel="noreferrer">10.2307/2963593</a></li><li><strong>McMillan, K. L. (2003)</strong>. <em>&quot;Interpolation and SAT-based model checking.&quot;</em><br><strong>Computer Aided Verification (CAV 2003)</strong>, LNCS 2725, pp. 1–13. DOI: <a href="https://doi.org/10.1007/978-3-540-45069-6_1" target="_blank" rel="noreferrer">10.1007/978-3-540-45069-6_1</a></li><li><strong>Pudlák, P. (1997)</strong>. <em>&quot;Lower bounds for resolution and cutting planes proofs and monotone computations.&quot;</em><br><strong>Journal of Symbolic Logic</strong>, 62(3), pp. 981–998. DOI: <a href="https://doi.org/10.2307/2275583" target="_blank" rel="noreferrer">10.2307/2275583</a></li></ul><h3 id="modelscript-rationale-modifications-2" tabindex="-1">ModelScript Rationale &amp; Modifications <a class="header-anchor" href="#modelscript-rationale-modifications-2" aria-label="Permalink to &quot;ModelScript Rationale &amp; Modifications&quot;">​</a></h3><p>Given unsatisfiable mutually contradictory formulas $A \\land B \\models \\bot$, Craig interpolation synthesizes an interpolant $I$ such that: $$A \\implies I \\quad \\text{and} \\quad I \\land B \\models \\bot$$ where $\\text{vars}(I) \\subseteq \\text{vars}(A) \\cap \\text{vars}(B)$.</p><ul><li><strong>Modifications</strong>: Employs Pudlák-McMillan resolution graph traversal to generate certified interpolants explaining cross-domain requirement violations without revealing proprietary subsystem equations.</li></ul><hr><h2 id="_4-hc4-constraint-contractor" tabindex="-1">4. HC4 Constraint Contractor <a class="header-anchor" href="#_4-hc4-constraint-contractor" aria-label="Permalink to &quot;4. HC4 Constraint Contractor&quot;">​</a></h2><h3 id="academic-citations-3" tabindex="-1">Academic Citations <a class="header-anchor" href="#academic-citations-3" aria-label="Permalink to &quot;Academic Citations&quot;">​</a></h3><ul><li><strong>Benhamou, F., Goualard, F., Granvilliers, L., &amp; Puget, J. F. (1999)</strong>. <em>&quot;Revising Hull and Box Consistency.&quot;</em><br><strong>International Conference on Logic Programming (ICLP&#39;99)</strong>, pp. 230–244.</li></ul><h3 id="modelscript-rationale-modifications-3" tabindex="-1">ModelScript Rationale &amp; Modifications <a class="header-anchor" href="#modelscript-rationale-modifications-3" aria-label="Permalink to &quot;ModelScript Rationale &amp; Modifications&quot;">​</a></h3><p>Evaluates non-linear algebraic constraints over interval domains without discretization grids:</p><ul><li><strong>Modifications</strong>: Two-phase HC4Revise operator: bottom-up forward evaluation of interval bounds followed by top-down backward narrowing; eliminates physically impossible state regions before numerical simulation.</li></ul><hr><h2 id="_5-signal-temporal-logic-stl-quantitative-monitor" tabindex="-1">5. Signal Temporal Logic (STL) Quantitative Monitor <a class="header-anchor" href="#_5-signal-temporal-logic-stl-quantitative-monitor" aria-label="Permalink to &quot;5. Signal Temporal Logic (STL) Quantitative Monitor&quot;">​</a></h2><h3 id="academic-citations-4" tabindex="-1">Academic Citations <a class="header-anchor" href="#academic-citations-4" aria-label="Permalink to &quot;Academic Citations&quot;">​</a></h3><ul><li><strong>Maler, O., &amp; Nickovic, D. (2004)</strong>. <em>&quot;Monitoring Temporal Properties of Continuous Signals.&quot;</em><br><strong>FORMATS/FTRTFT 2004</strong>, LNCS 3253, pp. 152–166. DOI: <a href="https://doi.org/10.1007/978-3-540-30206-3_12" target="_blank" rel="noreferrer">10.1007/978-3-540-30206-3_12</a></li><li><strong>Donzé, A., &amp; Maler, O. (2010)</strong>. <em>&quot;Robust Satisfaction of Temporal Logic over Real-Valued Signals.&quot;</em><br><strong>FORMATS 2010</strong>, LNCS 6246, pp. 92–106. DOI: <a href="https://doi.org/10.1007/978-3-642-15297-9_9" target="_blank" rel="noreferrer">10.1007/978-3-642-15297-9_9</a></li></ul><h3 id="modelscript-rationale-modifications-4" tabindex="-1">ModelScript Rationale &amp; Modifications <a class="header-anchor" href="#modelscript-rationale-modifications-4" aria-label="Permalink to &quot;ModelScript Rationale &amp; Modifications&quot;">​</a></h3><p>Monitors simulation trajectories against temporal specifications (e.g. &quot;overshoot must remain below 5% for at least 2 seconds after step input&quot;): $$\\rho(\\varphi, s, t) \\in \\mathbb{R}$$ Computes real-valued <strong>quantitative robustness</strong> indicating how far a trajectory is from violating safety boundaries.</p><hr><h2 id="_6-constrained-zonotopes" tabindex="-1">6. Constrained Zonotopes <a class="header-anchor" href="#_6-constrained-zonotopes" aria-label="Permalink to &quot;6. Constrained Zonotopes&quot;">​</a></h2><h3 id="academic-citations-5" tabindex="-1">Academic Citations <a class="header-anchor" href="#academic-citations-5" aria-label="Permalink to &quot;Academic Citations&quot;">​</a></h3><ul><li><strong>Scott, J. K., Raimondo, D. M., et al. (2016)</strong>. <em>&quot;Constrained zonotopes: A new tool for set-based estimation and fault detection.&quot;</em><br><strong>Automatica</strong>, 69, pp. 126–136. DOI: <a href="https://doi.org/10.1016/j.automatica.2016.02.036" target="_blank" rel="noreferrer">10.1016/j.automatica.2016.02.036</a></li></ul><h3 id="modelscript-rationale-modifications-5" tabindex="-1">ModelScript Rationale &amp; Modifications <a class="header-anchor" href="#modelscript-rationale-modifications-5" aria-label="Permalink to &quot;ModelScript Rationale &amp; Modifications&quot;">​</a></h3><p>Set-based reachability analysis under bounded initial states and parameter uncertainty. Closed under linear transformations, Minkowski addition, and hyperplanar intersection without facet explosion.</p><ul><li><strong>Modifications</strong>: Implemented as in-WASM linear algebraic routines utilizing singular value decomposition (SVD) for order reduction.</li></ul><hr><h2 id="upstream-downstream-pipeline-connections" tabindex="-1">Upstream &amp; Downstream Pipeline Connections <a class="header-anchor" href="#upstream-downstream-pipeline-connections" aria-label="Permalink to &quot;Upstream &amp; Downstream Pipeline Connections&quot;">​</a></h2><ul><li><strong>Upstream Inputs</strong>: <ul><li>Requirements ingested from <a href="./../languages/sysml2.html"><code>SysML v2</code></a>.</li><li>Trajectories simulated by <a href="./solvers-ode-dae.html"><code>Numerical Solvers</code></a>.</li><li>Spatial boundaries provided by <a href="./../languages/step.html"><code>STEP CAD</code></a>.</li></ul></li><li><strong>Downstream Consumers</strong>: <ul><li>Powers <code>msx verify</code>, generates compliance certificates, and exports mathematical proofs in <a href="./../reference/export-formats.html"><code>LaTeX format</code></a>.</li></ul></li></ul>',46)])])}const h=o(r,[["render",n]]);export{u as __pageData,h as default};
